from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT/'profile.json').read_text())
e=html.escape
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f4ef;color:#202d2b;font-family:-apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo","Noto Sans KR",sans-serif;line-height:1.75}a{color:inherit;text-underline-offset:5px}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #b16b32;outline-offset:5px}nav{max-width:1160px;margin:auto;padding:23px 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d4d9d0;gap:20px}nav .links{display:flex;flex-wrap:wrap;gap:24px;font-size:14px}nav a{text-decoration:none}.brand{font-weight:750;font-size:19px}main{max-width:1160px;margin:auto;padding:0 36px}.hero{padding:94px 0 78px;max-width:930px}.eyebrow{font:700 12px/1.5 system-ui;letter-spacing:2px;text-transform:uppercase;color:#567069}.hero h1{font-size:clamp(38px,5.4vw,65px);line-height:1.28;letter-spacing:-2.5px;font-weight:730;word-break:keep-all;margin:22px 0}.intro{max-width:650px;color:#52645c;font-size:18px;word-break:keep-all}.buttons{display:flex;flex-wrap:wrap;gap:12px;margin-top:32px}.button{display:inline-block;border:1px solid #304d42;border-radius:7px;padding:11px 20px;text-decoration:none;font-size:14px}.primary{background:#274c3e;color:white}.section{padding:54px 0;border-top:1px solid #d4d9d0}.section-title{display:flex;align-items:baseline;justify-content:space-between;gap:20px;margin-bottom:25px}.section-title h2{font-size:30px;letter-spacing:-1px;margin:0}.section-title span{color:#66736d;font-size:13px}.skills{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.skills h3{font-size:17px}.skills p{font-size:15px;color:#54645d}.projects{display:grid;gap:24px}.project{display:grid;grid-template-columns:1fr 1.4fr;background:#fff;border:1px solid #dce1d8;border-radius:14px;overflow:hidden}.project-head{padding:34px;background:#e9eee6}.project h3{font-size:26px;letter-spacing:-1px;line-height:1.35;margin:16px 0}.project-head p{color:#53695a}.stack{font-size:12px;line-height:1.7}.project-body{padding:28px 34px}.project-body h4{font-size:12px;color:#456b57;margin:13px 0 4px}.project-body p{font-size:15px;margin:0 0 15px}.career{display:grid;grid-template-columns:220px 1fr;gap:28px;padding:27px 0;border-bottom:1px solid #e1e4dc}.career h3{font-size:22px;margin:0}.muted{color:#67776e;font-size:13px}.role{font-weight:650;margin:0 0 12px}.career ul{padding-left:20px;margin:0;color:#46584f;font-size:15px}.career li{padding-bottom:7px}footer{max-width:1160px;margin:auto;padding:36px;font-size:13px;color:#67776e;border-top:1px solid #d4d9d0}.note{color:#68786c;font-size:13px}.skip{position:absolute;top:-100px}.skip:focus{top:8px;left:8px;background:white;padding:10px;z-index:99}@media(max-width:650px){nav{padding:20px}.links{gap:14px!important}main{padding:0 20px}.hero{padding:56px 0}.hero h1{letter-spacing:-1.7px}.intro{font-size:16px}.skills{grid-template-columns:1fr;gap:8px}.project{grid-template-columns:1fr}.project-head,.project-body{padding:24px}.career{grid-template-columns:1fr;gap:12px}.section-title{display:block}.section{padding:36px 0}footer{padding:25px 20px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
(ROOT/'styles.css').write_text(css)
head=lambda title:f'<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="홍현종의 백엔드, 개발 플랫폼 및 AI 업무 자동화 경력과 개인 프로젝트"><title>{e(title)}</title><link rel="stylesheet" href="styles.css"></head><body>'
nav='<a class="skip" href="#main">본문으로 이동</a><nav><a class="brand" href="index.html">홍현종<span class="muted"> / ENGINEER</span></a><div class="links"><a href="#projects">프로젝트</a><a href="#experience">경력</a><a href="resume.html">이력서 ↗</a></div></nav>'
projects=''
for i,p in enumerate(d['projects'],1):
 link=f'<a href="{e(p["link"])}">GitHub 코드 보기 ↗</a>' if p['link'] else '<span class="note">비공개 개인 프로젝트 · 소개만 공개</span>'
 projects+=f'<article class="project" id="{e(p["id"])}"><div class="project-head"><span class="eyebrow">0{i} / {e(p["category"])}</span><h3>{e(p["title"])}</h3><p>{e(p["subtitle"])}</p><p class="stack">{e(p["stack"])}</p>{link}</div><div class="project-body"><h4>문제</h4><p>{e(p["problem"])}</p><h4>접근과 구현</h4><p>{e(p["approach"])}</p><h4>결과와 범위</h4><p>{e(p["result"])}</p></div></article>'
def careers():
 return ''.join('<article class="career"><div><h3>'+e(c['company'])+'</h3><span class="muted">'+e(c['period'])+'</span></div><div><p class="role">'+e(c['role'])+'</p><ul>'+''.join('<li>'+e(b)+'</li>' for b in c['bullets'])+'</ul></div></article>' for c in d['careers'])
index=head('홍현종 | Backend & Developer Platform')+nav+'<main id="main"><section class="hero"><p class="eyebrow">Backend · Developer Platform · AI Automation</p><h1>'+e(d['headline'])+'</h1><p class="intro">'+e(d['summary'])+'</p><div class="buttons"><a class="button primary" href="#projects">대표 프로젝트 보기 ↓</a><a class="button" href="resume.html">이력서 읽기 ↗</a><a class="button" href="'+e(d['github'])+'">GitHub ↗</a></div></section><section class="section"><div class="skills">'+''.join('<div><h3>'+e(s['title'])+'</h3><p>'+e(s['body'])+'</p></div>' for s in d['skills'])+'</div></section><section class="section" id="projects"><div class="section-title"><h2>대표 개인 프로젝트</h2><span>SELECTED PERSONAL PROJECTS</span></div><div class="projects">'+projects+'</div></section><section class="section" id="experience"><div class="section-title"><h2>경력</h2><span>금융 · 결제 · 커머스 · 개발 플랫폼</span></div>'+careers()+'</section><section class="section"><h2>학력 및 자격</h2><p>'+e(d['education'])+'<br>'+e(d['certification'])+'</p></section></main><footer>홍현종 · <a href="'+e(d['github'])+'">GitHub</a> · 업데이트 '+e(d['updated'])+'<p>회사 업무는 수행 역할을 중심으로 요약했습니다. 개인 프로젝트의 구현 범위와 사업·운영 성과는 구분해 소개합니다.</p></footer></body></html>'
(ROOT/'index.html').write_text(index)
resume_css='''<style>body{background:white}main{max-width:880px}.resume-head{padding:44px 0 25px}h1{font-size:36px;margin:0}h2{font-size:22px;margin:24px 0 8px}.career{grid-template-columns:180px 1fr;gap:20px;padding:18px 0}.career h3{font-size:18px}.career li{font-size:14px;padding-bottom:4px}.role{font-size:14px}.summary{font-size:15px}.print-button{font:inherit;cursor:pointer}.project-mini{font-size:14px}button{background:white}@page{size:A4;margin:15mm 16mm}@media print{nav,.print-tools,footer{display:none}main{padding:0;max-width:none}body{font-size:10pt;line-height:1.5}.resume-head{padding:0 0 12px}h1{font-size:25pt}h2{font-size:14pt;break-after:avoid}.summary{font-size:10pt}.career{grid-template-columns:135px 1fr;padding:10px 0;break-inside:avoid}.career h3{font-size:12pt}.career li,.role,.project-mini{font-size:9.5pt}.muted{font-size:9pt}a{text-decoration:none}.resume-project{break-inside:avoid}}@media(max-width:650px){.career{grid-template-columns:1fr}}</style>'''
resume=head('홍현종 이력서')+resume_css+'<nav><a href="index.html">← 포트폴리오</a><div class="print-tools"><button class="button print-button" id="print">인쇄 / PDF 저장</button></div></nav><main><header class="resume-head"><h1>홍현종</h1><p>백엔드 · 개발 플랫폼 · AI 업무 자동화</p><a href="'+e(d['github'])+'">github.com/hhj4861</a></header><p class="summary">'+e(d['summary'])+'</p><h2>핵심 기술</h2><p class="summary">'+e(' / '.join(s['body'] for s in d['skills']))+'</p><h2>경력</h2>'+careers()+'<h2>개인 프로젝트</h2>'+''.join('<div class="resume-project"><p class="project-mini"><strong>'+e(p['title'])+'</strong> — '+e(p['subtitle'])+'<br>'+e(p['approach'])+'</p></div>' for p in d['projects'])+'<h2>학력 및 자격</h2><p class="summary">'+e(d['education'])+'<br>'+e(d['certification'])+'</p></main><script src="print.js"></script></body></html>'
(ROOT/'resume.html').write_text(resume)
(ROOT/'print.js').write_text("document.getElementById('print').addEventListener('click', () => window.print());\n")
md='# 홍현종\n\n백엔드 · 개발 플랫폼 · AI 업무 자동화\n\n'+d['summary']+'\n\n[포트폴리오](index.html) · [이력서](resume.html) · [GitHub]('+d['github']+')\n\n## 대표 프로젝트\n\n'
for p in d['projects']:
 md+='### '+p['title']+'\n\n'+p['problem']+'\n\n'+p['approach']+'\n\n'+p['result']+'\n\n'+('[코드 보기]('+p['link']+')\n\n' if p['link'] else '')
md+='## 경력\n\n'
for c in d['careers']: md+='### '+c['company']+' | '+c['period']+'\n\n'+c['role']+'\n\n'+''.join('- '+b+'\n' for b in c['bullets'])+'\n'
md+='## 업데이트\n\n`profile.json`을 수정하고 `python3 scripts/build.py`를 실행하면 웹 이력서와 포트폴리오가 함께 갱신됩니다. 개인정보·회사 내부 코드 및 증거 원문은 저장하지 않습니다.\n'
(ROOT/'README.md').write_text(md)
(ROOT/'.nojekyll').write_text('')
(ROOT/'.gitignore').write_text('.DS_Store\n__pycache__/\n.env*\n')
print('Generated index.html, resume.html, README.md and assets')
